raw:
{
  "summary": [
    {
      "text": "Эффективная толщина пласта равна общей толщине минус сумма толщин прослоев неколлектора.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "В терригенных разрезах выделяют три типа прослоев неколлектора по данным каротажа.",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "В глинистых коллекторах со слоистой глинистостью отдельные прослои не выделяются, толщина считается интегрально.",
      "claims": [
        "c3"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Эффективная толщина hэф определяется как разность общей толщины пласта h и суммы толщин прослоев неколлектора Σhпл.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Для терригенного разреза характерны три типа прослоев неколлектора: глины, плотные алевролиты и песчаники с глинистым цементом.",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "Первый тип выделяется повышенными показаниями микрозондов и низкими значениями kп < kп* при показаниях ГМ.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Плотные алевролиты и песчаники с неактивным цементом выделяются высокими значениями на диаграммах микрозондов и нейтронных методов.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Второй тип практически не прослеживается на диаграммах СП и ГМ, кроме случаев присутствия глинистого цемента.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "В пачке чередования тонких прослоев коллектора и глины отдельные прослои не выделяются даже микроэлектрическими методами.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "В этом случае суммарную эффективную толщину hэфΣ находят расчетным путем по интегральным характеристикам пачки.",
      "claims": [
        "c7"
      ]
    }
  ],
  "steps": [
    {
      "text": "Определить общую толщину пласта h.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Выделить прослои неколлектора по данным каротажа (микрозонды, ГМ, нейтронные методы).",
      "claims": [
        "c2",
        "c4",
        "c5"
      ]
    },
    {
      "text": "Суммировать толщины выделенных прослоев неколлектора (Σhпл).",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Вычесть сумму толщин прослоев из общей толщины пласта для получения hэф.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Если прослои слишком тонкие для выделения, рассчитать hэфΣ по интегральным характеристикам пачки.",
      "claims": [
        "c3",
        "c7"
      ]
    }
  ],
  "examples": [],
  "numbers": [
    {
      "text": "Условие выделения первого типа прослоев: kп < kп*.",
      "claims": [
        "c4"
      ]
    }
  ],
  "formulas": [
    {
      "unit": "u001-03",
      "latex": "h_{\\text{эф}} = h - \\sum h_{\\text{пл}}",
      "vars": [
        {
          "sym": "h_{\\text{эф}}",
          "meaning": "эффективная толщина",
          "unit": "м"
        },
        {
          "sym": "h",
          "meaning": "толщина всего пласта",
          "unit": "м"
        },
        {
          "sym": "\\sum h_{\\text{пл}}",
          "meaning": "сумма толщин прослоев неколлектора",
          "unit": "м"
        }
      ]
    }
  ],
  "misconception": {
    "wrong": "Каротажная кривая — это и есть порода, а не косвенное измерение.",
    "right": [
      {
        "text": "Прослои неколлектора выделяются по косвенным признакам (показаниям приборов), а не напрямую.",
        "claims": [
          "c2",
          "c4",
          "c5"
        ]
      }
    ]
  },
  "data_meaning": {
    "input": "Данные каротажа: показания микрозондов, ГМ, нейтронных методов, СП.",
    "output": "Эффективная толщина пласта hэф или hэфΣ.",
    "breaks": [
      {
        "text": "Метод не работает для пачек с чередованием тонких прослоев коллектора и глины, где отдельные прослои не выделяются.",
        "claims": [
          "c3"
        ]
      }
    ],
    "hypotheses": []
  },
  "analogy": {
    "text": "Выделение прослоев похоже на классификацию фич в данных: каждый тип прослоя имеет свой набор признаков (фичей), а порог kп* — это граница решающего правила.",
    "breaks_where": "Аналогия ломается, когда признаки перекрываются или прослои слишком тонкие для разрешения сенсора (как шум в данных)."
  },
  "now_practice": [],
  "layers": {
    "mechanism": [
      {
        "text": "Эффективная толщина вычисляется как разность общей толщины и суммы толщин неколлекторов.",
        "claims": [
          "c1"
        ]
      }
    ],
    "practice": [
      {
        "text": "Выделение прослоев выполняется по данным каротажа с использованием пороговых значений.",
        "claims": [
          "c2",
          "c4",
          "c5"
        ]
      }
    ],
    "nuances": [
      {
        "text": "Некоторые типы прослоев не видны на определенных диаграммах (СП, ГМ), если нет глинистого цемента.",
        "claims": [
          "c6"
        ]
      }
    ],
    "deeper": [
      {
        "text": "При слоистой глинистости переходят к интегральному расчету из-за ограничения разрешающей способности.",
        "claims": [
          "c3",
          "c7"
        ]
      }
    ]
  },
  "glossary": [
    {
      "term": "Прослой неколлектора",
      "en": "Non-reservoir layer",
      "definition": "Слой породы в пласте, не обладающий коллекторскими свойствами (проницаемостью)."
    },
    {
      "term": "Микрозонды",
      "en": "Microtools",
      "definition": "Методы каротажа с высокой разрешающей способностью по вертикали."
    },
    {
      "term": "kп",
      "en": "Permeability",
      "definition": "Проницаемость породы."
    },
    {
      "term": "ГМ",
      "en": "Gamma-ray logging",
      "definition": "Гамма-каротаж, метод измерения естественной радиоактивности."
    },
    {
      "term": "СП",
      "en": "Spontaneous potential",
      "definition": "Самопроизвольный потенциал, метод каротажа."
    }]}
